import { addDays, differenceInCalendarDays, format, parseISO } from 'date-fns'

/**
 * Pregnancy dating (FAM-03).
 *
 * Naegele's rule: 280 days from the first day of the last menstrual period.
 * This is arithmetic on a date the user typed, not an assessment — the clinic's
 * dating scan overrides it, and the UI says so. Nothing here classifies risk,
 * predicts an outcome, or flags anything as abnormal.
 */

export interface PregnancyDating {
  weeks: number
  days: number
  /** 1, 2, or 3. Null before conception dating makes sense. */
  trimester: 1 | 2 | 3 | null
  estimatedDueDate: string
  daysRemaining: number
  /** True once past 42 weeks, or before week 0 — both mean "ask, don't compute". */
  outOfRange: boolean
}

export const GESTATION_DAYS = 280

export function dating(lmpDate: string, today = new Date()): PregnancyDating {
  const lmp = parseISO(lmpDate)
  const elapsed = differenceInCalendarDays(today, lmp)
  const due = addDays(lmp, GESTATION_DAYS)

  const weeks = Math.floor(elapsed / 7)
  const days = ((elapsed % 7) + 7) % 7

  const outOfRange = elapsed < 0 || weeks > 42
  const trimester = outOfRange ? null : weeks < 14 ? 1 : weeks < 28 ? 2 : 3

  return {
    weeks,
    days,
    trimester,
    estimatedDueDate: format(due, 'yyyy-MM-dd'),
    daysRemaining: differenceInCalendarDays(due, today),
    outOfRange,
  }
}

/**
 * Which message describes this dating result. Returns a key rather than text so
 * the module stays free of copy — and deliberately offers no reassurance and no
 * warning, because the app is not qualified to give either.
 */
export function datingLabelKey(d: PregnancyDating): 'fam.outOfRange' | 'fam.week' {
  return d.outOfRange ? 'fam.outOfRange' : 'fam.week'
}
